#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, C;
    cin >> L >> C;

    vector<string> grid(L);
    for (int i = 0; i < L; ++i) {
        cin >> grid[i];
    }

    int sr = -1, sc = -1;
    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < C; ++j) {
            if (grid[i][j] == 'o') {
                sr = i;
                sc = j;
            }
        }
    }

    int r = sr, c = sc;
    int pr = -1, pc = -1;

    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    while (true) {
        int nr = -1, nc = -1;
        int cnt = 0;

        for (int d = 0; d < 4; ++d) {
            int rr = r + dr[d];
            int cc = c + dc[d];

            if (rr < 0 || rr >= L || cc < 0 || cc >= C) continue;
            if (grid[rr][cc] == '.') continue;
            if (rr == pr && cc == pc) continue;

            nr = rr;
            nc = cc;
            ++cnt;
        }

        if (cnt == 0) break;

        pr = r;
        pc = c;
        r = nr;
        c = nc;
    }

    cout << r + 1 << ' ' << c + 1 << '\n';

    return 0;
}
